INSERT INTO resources(scope_id,kind,schema_version,name,config,status) SELECT p.scope_id,'Skill',2,'RabbitMQ 健康诊断',jsonb_build_object('summary','RabbitMQ 集群、节点、队列、交换机、连接和消费者只读诊断。','owner','OpsKeeper builtin'),'active' FROM platforms p WHERE p.code='default' ON CONFLICT (scope_id,kind,lower(name)) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO skill_versions(skill_resource_id,version,manifest,input_schema,output_schema,tools,risk_level,status,published_at) SELECT r.id,COALESCE((SELECT max(v.version)+1 FROM skill_versions v WHERE v.skill_resource_id=r.id),1),jsonb_build_object('name',r.name,'description',r.config->>'summary','instruction','调用 RabbitMQ Management API 固定只读工具；不要执行写操作。','target_kinds','["RabbitMQ"]'::jsonb),'{}'::jsonb,'{}'::jsonb,'[{"name":"rabbitmq_health"},{"name":"rabbitmq_overview"},{"name":"rabbitmq_nodes"},{"name":"rabbitmq_queues"},{"name":"rabbitmq_exchanges"},{"name":"rabbitmq_connections"},{"name":"rabbitmq_channels"},{"name":"rabbitmq_consumers"},{"name":"rabbitmq_vhosts"}]'::jsonb,'read_only','published',now() FROM resources r WHERE r.kind='Skill' AND r.name='RabbitMQ 健康诊断' AND r.config->>'owner'='OpsKeeper builtin' ON CONFLICT (skill_resource_id,version) DO NOTHING;
